feed(chunk) { appendToPending(chunk);
 while(canResolveNextCharacter()) {
  if(inQuote) copyWithEscapeAndDoubledQuoteRules();
  else if(inLine) discardExceptNewline();
  else if(inBlock) discardUntilFirstStarSlashKeepingNewlines();
  else if(nextPairIsCommentOpener()) {emit(" "); enterComment(); consumePair();}
  else copyAndMaybeEnterQuote();
 }
}
finish() { resolvePendingAtEOF(); if(inBlock||inQuote)throw SyntaxError(); finished=true; }

strip(source) { const spans=[]; let i=0;
 while(i<source.length) {
  if(isQuote(source[i])) {const end=scanQuoted(source,i); spans.push(literal(i,end));i=end;}
  else if(isLineOpener(source,i)) {const end=scanToNewline(source,i+2);spans.push(comment(i,end));i=end;}
  else if(source.startsWith("/*",i)) {const end=scanFirstClosingPair(source,i+2);
   if(end<0)throw SyntaxError("unterminated block at "+i);spans.push(comment(i,end));i=end;}
  else {spans.push(plain(i,i+1));i++;}
 }
 return spans.map(s=>s.comment?" "+newlines(source.slice(s.start,s.end)):source.slice(s.start,s.end)).join("");
}
